rows=[dict(sem=a,code=b,course=c,credits=d,status=e,new_credits=f,new_sem=g,reason=h) for a,b,c,d,e,f,g,h in C]
with open("credit-map.csv","w",newline="") as fh:
    w=csv.DictWriter(fh,fieldnames=rows[0].keys()); w.writeheader(); w.writerows(rows)
old=sum(r["credits"] for r in rows); new=sum(r["new_credits"] for r in rows)
upd=sum(r["credits"] for r in rows if r["status"]=="UPDATE")
freed=sum(r["credits"]-r["new_credits"] for r in rows if r["status"]=="REDUCE")
added=sum(r["new_credits"] for r in rows if r["status"]=="ADD")
aff=upd+freed+added
per=lambda k,key:{s:sum(r[key] for r in rows if r[k]==s) for s in range(1,8)}
summary=f"""# Credit map summary (generated by build_credit_map.py)
Current total: {old} | Proposed total: {new} | UPDATE credits: {upd} | Freed by REDUCE: {freed} | Added: {added}
Affected credits = {upd} + {freed} + {added} = {aff} = {aff/old*100:.1f}% of {old}
Current per semester: {list(per('sem','credits').values())}
Proposed per semester: {list(per('new_sem','new_credits').values())}
"""
open("credit-map-summary.txt","w").write(summary); print(summary)
tpl=open("calculator/index.template.html").read()
